import{_ as e,o as r,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-02-07","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-02-07","date":"2022-02-07T00:00:00.000Z","updated":"2022-02-12T00:00:00.000Z","tags":["Ceph升级","分布式存储","Ceph集群管理","Ceph性能优化","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-07.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-02-07.md","lastUpdated":1780460162000}'),p={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-02-07.md"};function n(i,t,l,a,_,g){return r(),s("div",null,[...t[0]||(t[0]=[o("<p>在2022年2月7日的Ceph Orchestrator会议中，Ceph研发团队成员讨论了与Ceph升级相关的问题，并提出了改进方案。</p><p><strong>主要议题</strong>：</p><ol><li><p><strong>升级过程中的OSD依赖问题</strong>：在升级过程中，OSD依赖于CRUSH map，导致在升级监控器后所有OSD需要重新配置，这在大型集群中会显著减慢升级速度，并影响用户体验。会议讨论了延迟OSD重新配置的可行性，以减少不必要的重新配置时间。</p></li><li><p><strong>升级过程的粒度控制</strong>：大型集群的用户希望更细粒度地控制升级过程，例如按主机或按守护进程类型进行升级，以便更好地管理升级过程和减少潜在的风险。会议决定实现按主机和按守护进程类型的升级选项，并确保升级顺序的正确性。</p></li></ol><p><strong>讨论内容</strong>：</p><ul><li><strong>OSD依赖问题</strong>：讨论了延迟OSD重新配置的潜在风险，并考虑了其他升级策略，如参考Ansible的升级方法。</li><li><strong>升级粒度控制</strong>：讨论了按主机和按守护进程类型的升级选项，以及如何改进升级状态显示。</li></ul><p><strong>决定事项</strong>：</p><ul><li>探索延迟OSD重新配置的可行性，并评估其潜在风险。</li><li>实现按主机和按守护进程类型的升级选项，并确保升级顺序的正确性。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>进行技术调研，进一步研究延迟OSD重新配置的技术细节和潜在风险。</li><li>开发按主机和按守护进程类型的升级选项，并确保升级顺序的正确性。</li><li>改进升级状态显示，提供更详细的升级进度信息。</li></ul><p>此外，会议还讨论了离线主机处理、升级状态显示以及如何处理版本兼容性问题。</p>",10)])])}const d=e(p,[["render",n]]);export{h as __pageData,d as default};
